NOMES_IGUAIS = True


def dec(b64):
    return zlib.decompress(base64.b64decode(b64))


def sha(b):
    return hashlib.sha256(b).hexdigest()


def sha_arq(p):
    h = hashlib.sha256()
    with open(p, "rb") as fh:
        for c in iter(lambda: fh.read(1 << 20), b""):
            h.update(c)
    return h.hexdigest()


def ler_mpk(path):
    with open(path, "rb") as fh:
        cab = fh.read(12)
        if cab[:4] != b"MPK1":
            raise ValueError("MPK1 inválido: " + str(path))
        count, names_bytes = struct.unpack("<II", cab[4:])
        brutas = fh.read(12 * count)
        blob = fh.read(names_bytes)
        nomes = {}
        for i in range(count):
            name_at, off, size = struct.unpack_from("<III", brutas, i * 12)
            fim = blob.index(0, name_at)
            nomes[blob[name_at:fim].decode()] = (off, size)
        return nomes


def reconstruir_mpk(destino, overlay):
    """Regrava o MPK1 no lugar: entradas atuais + overlay (streaming)."""
    atuais = ler_mpk(destino)
    nomes = sorted(set(atuais) | set(overlay))
    blob = b"".join(n.encode() + b"\0" for n in nomes)
    header = 12 + 12 * len(nomes) + len(blob)
    offset = (header + 31) & ~31
    registros = []
    name_at = 0
    tamanhos = {n: (len(overlay[n]) if n in overlay else atuais[n][1]) for n in nomes}
    for n in nomes:
        registros.append((name_at, offset, tamanhos[n]))
        name_at += len(n.encode()) + 1
        offset += (tamanhos[n] + 31) & ~31
    if offset >= 1 << 31:
        raise ValueError("MPK1 excede o alcance de seek")
    tmp = Path(str(destino) + ".nova")
    with open(destino, "rb") as src, open(tmp, "wb") as out:
        out.write(b"MPK1" + struct.pack("<II", len(nomes), len(blob)))
        for r in registros:
            out.write(struct.pack("<III", *r))
        out.write(blob)
        out.write(bytes(((header + 31) & ~31) - header))
        for n, r in zip(nomes, registros):
            if n in overlay:
                dados = overlay[n]
            else:
                off, size = atuais[n]
                src.seek(off)
                dados = src.read(size)
                if len(dados) != size:
                    raise ValueError("MPK1 truncado: " + n)
            out.write(dados)
            out.write(bytes(((len(dados) + 31) & ~31) - len(dados)))
    os.replace(tmp, destino)


def achar_port(argv):
    for a in argv:
        if a not in ("--check", "--restore") and not a.startswith("-"):
            return Path(a)
    achado = None
    for letra in "DEFGHIJKLMNOPQRSTUVWXYZ":
        p = Path(letra + ":/") / "ports" / "mkwiita-nextos"
        if (p / "runtime" / "pc" / "PC-PREPARE.json").is_file():
            achado = p
            break
    if achado is not None:
        resposta = input("Caminho do port [%s]: " % achado).strip().strip('"')
        return Path(resposta) if resposta else achado
    return Path(input("Caminho do port mkwiita-nextos: ").strip().strip('"'))


def validacoes(port):
    cozido = port / "data" / "cooked"
    if not (cozido / "ui-data").is_dir():
        raise SystemExit("[X] não parece um port mkwiita-nextos: " + str(port))
    ct = cozido / "content.txt"
    if ct.is_file() and ct.read_text(encoding="utf-8").strip() != CONTEUDO_ESPERADO:
        print("[!] content.txt difere do contrato do port")
    for pak in PAKS:
        if not (cozido / pak).is_file():
            raise SystemExit("[X] ausente no port: " + pak)
    return cozido


def estado_small(cozido):
    """[(rel, caminho, estado)] estado: igual|aplicar|restaurar"""
    out = []
    for rel, b64 in sorted(PT_SMALL.items()):
        p = cozido / rel.replace("/", os.sep)
        if not p.is_file():
            out.append((rel, p, "aplicar"))
            continue
        atual = sha_arq(p)
        pt = sha(dec(b64))
        en = sha(dec(EN_SMALL[rel])) if rel in EN_SMALL else None
        if atual == pt:
            out.append((rel, p, "igual"))
        elif en is not None and atual == en:
            out.append((rel, p, "aplicar"))
        else:
            out.append((rel, p, "aplicar"))
    return out


def estado_pak(cozido, pak, payload):
    """'igual' se todas as entradas PT já estão com o mesmo conteúdo."""
    p = cozido / pak
    atuais = ler_mpk(p)
    for nome, b64 in payload.get(pak, {}).items():
        if nome not in atuais:
            return "aplicar"
        off, size = atuais[nome]
        with open(p, "rb") as fh:
            fh.seek(off)
            if hashlib.sha256(fh.read(size)).hexdigest() != sha(dec(b64)):
                return "aplicar"
    return "igual"


def atualizar_manifest(cozido, rels):
    man_path = cozido / "manifest.json"
    man = json.loads(man_path.read_text(encoding="utf-8"))
    n = 0
    for rel in rels:
        p = cozido / rel.replace("/", os.sep)
        if p.is_file() and rel in man:
            man[rel] = sha_arq(p)
            n += 1
    man_path.write_text(json.dumps(man, indent=2) + "\n", encoding="utf-8", newline="\n")
    return n


def atualizar_recibo(port, rels):
    rec_path = port / ".nxrelease" / "prepared" / "PREPARED.json"
    if not rec_path.is_file():
        print("[i] sem PREPARED.json; recibo não atualizado")
        return
    rec = json.loads(rec_path.read_text(encoding="utf-8"))
    rows = rec["outputs"]
    quer = {"data/cooked/" + r for r in rels}
    n = 0
    for row in rows:
        if row["path"] in quer:
            p = port / row["path"]
            if p.is_file():
                row["bytes"] = p.stat().st_size
                row["sha256"] = sha_arq(p)
                n += 1
    rec["chain_sha256"] = hashlib.sha256(json.dumps(rows, sort_keys=True).encode()).hexdigest()
    rec_path.write_text(json.dumps(rec, indent=2) + "\n", encoding="utf-8", newline="\n")
    print("recibo PREPARED.json: %d rows atualizadas, chain recalculada" % n)


def aplicar(cozido, pt=True, pak_payload=None):
    """Aplica (pt=True) ou restaura (pt=False). Retorna rels alterados."""
    small = PT_SMALL if pt else EN_SMALL
    paks = pak_payload if pak_payload is not None else (PT_PAK if pt else EN_PAK)
    alterados = []
    for rel, b64 in sorted(small.items()):
        dst = cozido / rel.replace("/", os.sep)
        if pt:
            bak = cozido / "_backup_traducao" / rel.replace("/", os.sep)
            if not bak.is_file() and dst.is_file():
                bak.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(dst, bak)
        dst.parent.mkdir(parents=True, exist_ok=True)
        dst.write_bytes(dec(b64))
        alterados.append(rel)
    for pak in PAKS:
        overlay = {nome: dec(b64) for nome, b64 in sorted(paks.get(pak, {}).items())}
        if overlay or not pt:
            reconstruir_mpk(cozido / pak, overlay)
        alterados.append(pak)
    return alterados


def pausa():
    try:
        input("\nPressione Enter para sair...")
    except Exception:
        pass


def main():
    check = "--check" in sys.argv
    restore = "--restore" in sys.argv
    interativo = len(sys.argv) <= 1
    print('%s — v%s' % (APP_TITLE, APP_VERSION))
    print('Tradução: %s' % TRADUCAO_CREDITO)
    print()
    port = achar_port(sys.argv[1:])
    cozido = validacoes(port)

    if restore:
        print("== restaurando inglês ==")
        rels = aplicar(cozido, pt=False)
        atualizar_manifest(cozido, rels)
        atualizar_recibo(port, rels)
        print("restaurado (%d arquivos/entradas)." % len(rels))
        if interativo: pausa()
        return

    print("== verificando o port ==")
    estado = estado_small(cozido)
    pend_small = [(rel, p, st) for rel, p, st in estado if st == "aplicar"]
    pend_pak = [p for p in PAKS if estado_pak(cozido, p, PT_PAK) == "aplicar"]
    if check:
        for rel, _p, st in estado:
            print("  %-52s %s" % (rel, "igual" if st == "igual" else "aplicar"))
        for pak in PAKS:
            print("  %-52s %s" % (pak, "igual" if pak not in pend_pak else "aplicar"))
    else:
        print("  %d de %d arquivos soltos já em PT" % (len(estado) - len(pend_small), len(estado)))
        for rel, _p, st in pend_small:
            print("  %-52s aplicar" % rel)
        for pak in PAKS:
            print("  %-52s %s" % (pak, "já em PT" if pak not in pend_pak else "aplicar"))

    if check:
        if interativo: pausa()
        return
    if not pend_small and not pend_pak:
        print("\nNada a fazer: tradução completa já aplicada.")
        if interativo: pausa()
        return

    print("\n== aplicando tradução completa ==")
    rels = aplicar(cozido, pt=True)
    n = atualizar_manifest(cozido, rels)
    atualizar_recibo(port, rels)
    print("\nTradução PT-BR COMPLETA aplicada! (%d soltos + %d paks reconstruídos; manifest: %d hashes)"
          % (len(PT_SMALL), len(PAKS), n))
    print('Para voltar ao inglês: py -3 "Mario Kart Wii PT-BR.py" --restore')
    if interativo: pausa()


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        if len(sys.argv) <= 1:
            pausa()
        raise
